Каждая строка рисунка выводится отдельной командой `cout`:

```cpp
cout << "******************" << endl;
cout << "*                *" << endl;
cout << "*                *" << endl;
cout << "******************" << endl;
```

```cpp
1  #include <iostream>
2  using namespace std;
3  int main ()
4  {
5  cout<<"Привет!"<<endl;
6  cout <<Я ученик 7 класса<<endl;
7  cout <"Это моя первая программа"<<endl;
8  cout <<"---------------"<<endl
9  return 0;
10 }
```

- строка 6 — пропущены кавычки вокруг текста;
- строка 7 — пропущен знак `<` (нужно `<<`);
- строка 8 — пропущена точка с запятой в конце.

#include <iostream>
int main ()
{
std::string a;
std::cout<<"Как тебя зовут?"<<std::endl;
std::cin>>a;
std::cout<<a<<", здравствуй!"<<std::endl;
}

#include <iostream>
using namespace std;
int main ()
{
string a;
cout<<"Как тебя зовут?"<<endl;
cin>>a;
cout<<a<<", здравствуй!"<<endl;
}

